import {nalr,FREQ,PROFILES} from './dsp.js';
import {toFullCircle,lookup,personalize,itdMicroseconds,headWidthToItdScale,serialize} from './hrtf.js';
const $=s=>document.querySelector(s);let ctx,node,analyser,micStream,micSource,ready=false,recording=false,kemar=null,customSet=null,activeSet=null;
const p={mode:'A',left:[...PROFILES.sloping],right:[...PROFILES.sloping],target:0,masker:90,head:0,snr:5,noise:'noise',directional:false,ratio:2,attack:10,release:150,delay:0,direct:0,volume:-24,feedback:false,feedbackGain:-25,feedbackVariant:'nominal',afc:false,afcMode:'pem',afcStep:.004,freqShift:0};
function status(s){$('#status').textContent=s;}
function send(){node?.port.postMessage({type:'config',value:p});drawScene();drawGain();}
function audiogram(){const parent=$('#audiogram');parent.replaceChildren();parent.append(document.createElement('span'));for(const f of FREQ){const x=document.createElement('span');x.textContent=f>=1000?f/1000+'k':f;parent.append(x);}for(const ear of ['left','right']){const label=document.createElement('span');label.textContent=ear==='left'?'L':'R';parent.append(label);p[ear].forEach((v,i)=>{const input=document.createElement('input');input.type='number';input.min=0;input.max=90;input.step=5;input.value=v;input.setAttribute('aria-label',`${ear} threshold ${FREQ[i]} Hz`);input.onchange=()=>{input.value=Math.max(0,Math.min(90,Number(input.value)||0));p[ear][i]=Number(input.value);send();};parent.append(input);});}}
function drawScene(){for(const name of ['target','masker']){const a=p[name]*Math.PI/180;$('#'+name+'Dot').setAttribute('transform',`translate(${260+125*Math.sin(a)} ${185-125*Math.cos(a)})`);}$('#headShape').setAttribute('transform',`rotate(${p.head} 260 185)`);}
function drawGain(){const c=$('#gain'),g=c.getContext('2d'),w=c.width,h=c.height;g.clearRect(0,0,w,h);g.font='13px sans-serif';g.strokeStyle='#2b4148';g.fillStyle='#a4bbc1';for(let v=0;v<=50;v+=10){let y=175-v*2.8;g.beginPath();g.moveTo(44,y);g.lineTo(w-20,y);g.stroke();g.fillText(v+' dB',3,y+4);}for(let i=0;i<6;i++)g.fillText(FREQ[i]+'',45+i*98,199);for(let e=0;e<2;e++){const vals=nalr(p[e?'right':'left']);g.strokeStyle=g.fillStyle=e?'#e9ad80':'#a1dec7';g.beginPath();vals.forEach((v,i)=>{let x=55+i*98,y=175-v*2.8;i?g.lineTo(x,y):g.moveTo(x,y);});g.stroke();vals.forEach((v,i)=>{g.beginPath();g.arc(55+i*98,175-v*2.8,3.5,0,7);g.fill();});}g.fillStyle='#a1dec7';g.fillText('Left target',390,20);g.fillStyle='#e9ad80';g.fillText('Right target',490,20);}
function normalized(x){let s=0;for(const v of x)s+=v*v;const scale=.05/Math.max(Math.sqrt(s/x.length),1e-8);return Float32Array.from(x,v=>v*scale);}
async function loadAudio(url,index){const response=await fetch(url);if(!response.ok)throw Error(`Could not load ${url}`);const b=await ctx.decodeAudioData(await response.arrayBuffer());node.port.postMessage({type:'source',index,value:normalized(b.getChannelData(0))});}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function wav(channels){let n=channels[0].length,b=new ArrayBuffer(44+n*4),v=new DataView(b);const str=(i,s)=>{for(let j=0;j<s.length;j++)v.setUint8(i+j,s.charCodeAt(j));};str(0,'RIFF');v.setUint32(4,36+n*4,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,2,true);v.setUint32(24,ctx.sampleRate,true);v.setUint32(28,ctx.sampleRate*4,true);v.setUint16(32,4,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*4,true);for(let i=0;i<n;i++)for(let e=0;e<2;e++)v.setInt16(44+i*4+e*2,Math.max(-1,Math.min(1,channels[e][i]))*32767,true);return new Blob([b],{type:'audio/wav'});}
async function init(){if(ready)return;status('Loading measured acoustics and audio…');ctx=new AudioContext({sampleRate:44100,latencyHint:'interactive'});if(ctx.sampleRate!==44100)throw Error('This measured-HRIR edition requires a 44.1 kHz audio context.');await ctx.audioWorklet.addModule('processor.js');node=new AudioWorkletNode(ctx,'hearing-processor',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[2]});node.onprocessorerror=()=>status('Audio processor error. Reload to reset.');node.port.onmessage=({data:d})=>{if(d.type==='meter'){for(const e of ['left','right'])$('#'+e+'Meter').textContent=(20*Math.log10(d[e]+1e-12)).toFixed(1);if(d.feedback)feedbackTelemetry(d.feedback);}if(d.type==='error')status(d.message);if(d.type==='record'){download(wav(d.channels),'hearing-lab-10s.wav');recording=false;$('#record').disabled=false;$('#record').textContent='Capture 10 s WAV';status('10-second capture exported');}};const response=await fetch('assets/kemar-horizontal.json');if(!response.ok)throw Error('HRIR data missing. Run research/restore_data.py.');kemar=toFullCircle(await response.json());await applyHRTF();await Promise.all([loadAudio('assets/speech.wav',0),loadAudio('assets/interferer.wav',1)]);send();analyser=ctx.createAnalyser();analyser.fftSize=512;node.connect(analyser);analyser.connect(ctx.destination);ready=true;$('#quantum').textContent=(128000/ctx.sampleRate).toFixed(2);$('#latency').textContent=`${ctx.sampleRate} Hz · browser base + output estimate ${((ctx.baseLatency+(ctx.outputLatency||0))*1000).toFixed(1)} ms. This estimate excludes some device and acoustic delays; measure with loopback for end-to-end latency.`;spectrum();}
function spectrum(){const data=new Uint8Array(analyser.frequencyBinCount);analyser.getByteFrequencyData(data);const c=$('#spectrum'),g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);g.fillStyle='#79bba5';for(let i=0;i<128;i++){let h=data[i]*.5;g.fillRect(i*c.width/128,c.height-h-8,3,h);}requestAnimationFrame(spectrum);}
$('#play').onclick=async()=>{try{if(!ready){await init();await ctx.resume();}else if(ctx.state==='running'){await ctx.suspend();}else await ctx.resume();$('#play').textContent=ctx.state==='running'?'Pause':'Resume';status(ctx.state==='running'?'Playing · measured binaural scene':'Paused');}catch(e){status(e.message);await ctx?.close();ctx=null;node=null;ready=false;}};
for(const id of ['target','masker','head','ratio','attack','release','delay','direct','volume'])$('#'+id).oninput=e=>{p[id]=Number(e.target.value);const units=['target','masker','head'].includes(id)?'°':id==='ratio'?':1':id==='volume'?' dB':id==='direct'?'%':' ms';$('#'+id+'-value').textContent=(id==='direct'?Math.round(p[id]*100):p[id])+units;send();};
for(const id of ['snr','noise'])$('#'+id).onchange=e=>{p[id]=id==='snr'?Number(e.target.value):e.target.value;send();};$('#directional').onchange=e=>{p.directional=e.target.checked;send();};
for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>{p.mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b));send();};
$('#profile').onchange=e=>{const name=e.target.value;p.left=[...(PROFILES[name]||PROFILES.sloping)];p.right=name==='asymmetric'?[25,35,45,60,65,70]:[...p.left];audiogram();send();};
$('#upload').onchange=async e=>{try{await init();const file=e.target.files[0];if(!file)return;const b=await ctx.decodeAudioData(await file.arrayBuffer());node.port.postMessage({type:'source',index:0,value:normalized(b.getChannelData(0))});status(`Loaded ${file.name} · first channel normalized`);}catch(e){status(e.message);}};
$('#mic').onclick=async()=>{try{await init();if(micStream){micSource.disconnect();micStream.getTracks().forEach(t=>t.stop());micStream=null;$('#mic').textContent='Use microphone';status('Returned to file target');}else{micStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});micSource=ctx.createMediaStreamSource(micStream);micSource.connect(node);$('#mic').textContent='Stop microphone';status('Microphone active · scene SNR is uncalibrated');}await ctx.resume();$('#play').textContent='Pause';}catch(e){status('Microphone: '+e.message);}};
$('#record').onclick=async()=>{try{await init();await ctx.resume();$('#play').textContent='Pause';if(recording)return;recording=true;$('#record').disabled=true;$('#record').textContent='Recording 10 seconds…';node.port.postMessage({type:'record'});}catch(e){status(e.message);}};
$('#export').onclick=()=>download(new Blob([JSON.stringify({version:'0.5.0',parameters:p,hrtf:activeSet?{source:activeSet.source,personalization:activeSet.personalization,itd_90_us:itdMicroseconds(lookup(activeSet,90))}:null,sampleRate:ctx?.sampleRate||44100,source:'current browser source; audio not embedded',scope:'educational, not calibrated'},null,2)],{type:'application/json'}),'hearing-lab-settings.json');
const baseline=new URLSearchParams(location.search).get('baseline');if(baseline){p.mode='D';p.ratio=baseline==='nalr'?1:2;p.directional=baseline==='direction';$('#ratio').value=p.ratio;$('#ratio-value').textContent=p.ratio+':1';$('#directional').checked=p.directional;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x.dataset.mode==='D'));}audiogram();send();

// 05 · Simulated feedback loop and adaptive canceller (mode D only).
let lastClips=0,delayNote='';
function feedbackTelemetry(f){const fresh=f.receiver_clips>lastClips;lastClips=f.receiver_clips;$('#fbMis').textContent=f.misalignment_db?f.misalignment_db[0].toFixed(1):'—';$('#fbMsg').textContent=(f.afc?f.msg_bound_db.with_afc[0]:f.msg_bound_db.without_afc).toFixed(1);$('#fbClips').textContent=f.active?f.receiver_clips.toLocaleString():'—';$('#fbStatus').textContent=delayNote+(!p.feedback?'Feedback path off.':p.mode!=='D'?'Feedback is simulated in condition D only; select D to close the loop.':fresh?`Receiver saturating: the loop is unstable (howling)${f.afc?' — the canceller is still converging or cannot keep up':''}. ${f.afc?'Wait a second, or lower':'Lower'} the path gain${f.afc?'':' or enable the canceller'}.`:f.afc?`Loop stable with ${f.afc_mode==='pem'?'PEM':'NLMS'} cancellation. Misalignment below about −10 dB means the canceller has learned most of the path${f.pitch_lag_ms?`; speech model pitch lag ${f.pitch_lag_ms.toFixed(1)} ms`:''}.`:'Loop stable without cancellation: the path gain is below the margin for the current fitting.');}
$('#fbOn').onchange=e=>{p.feedback=e.target.checked;send();};$('#afcOn').onchange=e=>{p.afc=e.target.checked;delayNote='';if(p.afc&&p.delay<1){p.delay=4;$('#delay').value=4;$('#delay-value').textContent='4 ms';delayNote='Added delay set to 4 ms: with no forward-path delay the canceller learns the incoming sound instead of the feedback path and makes the loop unstable (see the delay ablation). ';}send();};
$('#fbGain').oninput=e=>{p.feedbackGain=Number(e.target.value);$('#fbGain-value').textContent=p.feedbackGain+' dB';send();};
$('#afcMode').onchange=e=>{p.afcMode=e.target.value;send();};$('#afcStep').onchange=e=>{p.afcStep=Number(e.target.value);send();};$('#freqShift').onchange=e=>{p.freqShift=Number(e.target.value);send();};
$('#fbPhone').onclick=()=>{p.feedbackVariant=p.feedbackVariant==='nominal'?'changed':'nominal';$('#fbPhone').textContent=p.feedbackVariant==='nominal'?'Bring phone to ear (+12 dB)':'Remove phone (nominal path)';send();};
// 06 · HRTF set selection and anthropometric personalization.
let hrtfTimer=0;
async function applyHRTF(){if(!kemar)return;const mode=$('#hrtfSet').value,width=Number($('#headWidth').value),spec=Number($('#spectral').value);try{if(mode==='custom'&&!customSet){$('#hrtfInfo').textContent='Load an HRTF JSON file to use a custom set; KEMAR remains active.';activeSet=kemar;}else activeSet=mode==='custom'?customSet:mode==='scaled'?personalize(kemar,{itdScale:headWidthToItdScale(width),spectralScale:spec}):kemar;node?.port.postMessage({type:'hrir',value:serialize(activeSet)});const i=itdMicroseconds(lookup(activeSet,90)),k=itdMicroseconds(lookup(kemar,90));if(mode!=='custom'||customSet)$('#hrtfInfo').textContent=`Active: ${activeSet.source}${activeSet.personalization?` · ITD ×${activeSet.personalization.itd_scale.toFixed(3)}, spectral ×${activeSet.personalization.spectral_scale.toFixed(2)}`:''}. ITD at 90°: ${i.toFixed(0)} µs (KEMAR ${k.toFixed(0)} µs).`;}catch(e){$('#hrtfInfo').textContent='HRTF: '+e.message;}}
$('#hrtfSet').onchange=()=>applyHRTF();
for(const id of ['headWidth','spectral'])$('#'+id).oninput=e=>{$('#'+id+'-value').textContent=id==='headWidth'?Number(e.target.value).toFixed(1)+' cm':Number(e.target.value).toFixed(2)+'×';if($('#hrtfSet').value!=='scaled'){$('#hrtfSet').value='scaled';}clearTimeout(hrtfTimer);hrtfTimer=setTimeout(applyHRTF,150);};
$('#hrtfFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const set=toFullCircle(JSON.parse(await file.text()));customSet={...set,source:set.source==='unspecified'?file.name:set.source};$('#hrtfSet').value='custom';await applyHRTF();}catch(err){$('#hrtfInfo').textContent=`Could not use ${file.name}: ${err.message}`;}};
